"""CSS that swaps Streamlit's running-indicator icons for market ones."""

CSS = '<style>\n/* Running indicator (top right, beside Deploy): bar chart, money bag and Bitcoin\n   instead of Streamlit\'s swimmer / plane / runner icons. Same size and grey. */\n[data-testid="stStatusWidgetRunningIcon"] svg { display: none !important; }\n[data-testid="stStatusWidgetRunningIcon"]::before { content: ""; display: block; width: 1.6rem; height: 1.6rem;\n    background: no-repeat center / contain; animation: md-running-icons 2.4s infinite; }\n@keyframes md-running-icons {\n    0%, 33.2% { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22rgba(247,248,250,0.6)%22%3E%3Crect x=%224%22 y=%2212%22 width=%224%22 height=%228%22 rx=%221%22/%3E%3Crect x=%2210%22 y=%225%22 width=%224%22 height=%2215%22 rx=%221%22/%3E%3Crect x=%2216%22 y=%229%22 width=%224%22 height=%2211%22 rx=%221%22/%3E%3C/svg%3E"); }\n    33.3%, 66.5% { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22rgba(247,248,250,0.6)%22%3E%3Cpath d=%22M8.5 2.5h7l-2 3.5h-3z%22/%3E%3Cpath d=%22M10 7h4c3.6 2.2 6 5.6 6 9.2 0 3.1-2.9 5.3-8 5.3s-8-2.2-8-5.3C4 12.6 6.4 9.2 10 7z%22/%3E%3Ctext x=%2212%22 y=%2219%22 text-anchor=%22middle%22 font-family=%22Helvetica,Arial,sans-serif%22 font-weight=%22700%22 font-size=%229.5%22 fill=%22%23141414%22%3E%24%3C/text%3E%3C/svg%3E"); }\n    66.6%, 100% { background-image: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Ccircle cx=%2212%22 cy=%2212%22 r=%229.5%22 fill=%22rgba(247,248,250,0.6)%22/%3E%3Ctext x=%2212%22 y=%2216.6%22 text-anchor=%22middle%22 font-family=%22Helvetica,Arial,sans-serif%22 font-weight=%22700%22 font-size=%2213%22 fill=%22%23141414%22 transform=%22rotate(14 12 12)%22%3E%E2%82%BF%3C/text%3E%3C/svg%3E"); }\n}\n</style>'
